mapper.sql:
WHERE so.status > 0 AND company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

    AND (
        so_code LIKE CONCAT('%', #{filter.searchText}, '%')
        OR customers.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND so.order_date >= #{filter.dateFrom}


    AND so.order_date <= #{filter.dateTo}

mapper.select:
SELECT so.id AS id, so_code AS invoiceCode, customers.name AS organizationName, DATE(so.created) AS created, FORMAT(, 2) AS totalAmount FROM sales_orders so INNER JOIN customers ON customers.id = so.customer_id
HAVING totalAmount > 0 ORDER BY invoiceCode ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}
